import{_ as l,a0 as o,w as d,s as r,I as e,x as a,a1 as t,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"系统管理员需知的 16 个 iptables 使用技巧 | LCTT x X-CMD","titleTemplate":false,"description":"系统管理员需知的 16 个 iptables 使用技巧 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"系统管理员需知的 16 个 iptables 使用技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"系统管理员需知的 16 个 iptables 使用技巧 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181001 16 iptables tips and tricks for sysadmins","title":"系统管理员需知的 16 个 iptables 使用技巧","tag":"201810","desc":""},"relativePath":"201810/20181001 16 iptables tips and tricks for sysadmins.md","filePath":"[post].md"}'),h={name:"201810/20181001 16 iptables tips and tricks for sysadmins.md"};function c(b,s,k,g,u,f){const i=o("Link");return d(),r("div",null,[s[30]||(s[30]=e("h1",{id:"系统管理员需知的-16-个-iptables-使用技巧",tabindex:"-1"},[a("系统管理员需知的 16 个 iptables 使用技巧 "),e("a",{class:"header-anchor",href:"#系统管理员需知的-16-个-iptables-使用技巧","aria-label":"Permalink to “系统管理员需知的 16 个 iptables 使用技巧”"},"​")],-1)),s[31]||(s[31]=e("blockquote",null,[e("p",null,"iptables 是一款控制系统进出流量的强大配置工具。")],-1)),s[32]||(s[32]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/command_line_prompt.png?itok=wbGiJ_yg",alt:""})],-1)),e("p",null,[s[2]||(s[2]=a("现代 Linux 内核带有一个叫 ",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Netfilter"},{default:n(()=>[...s[0]||(s[0]=[a("Netfilter",-1)])]),_:1}),s[3]||(s[3]=a(" 的数据包过滤框架。Netfilter 提供了允许、丢弃以及修改等操作来控制进出系统的流量数据包。基于 Netfilter 框架的用户层命令行工具 ",-1)),s[4]||(s[4]=e("code",null,"iptables",-1)),s[5]||(s[5]=a(" 提供了强大的防火墙配置功能，允许你添加规则来构建防火墙策略。",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Iptables"},{default:n(()=>[...s[1]||(s[1]=[a("iptables",-1)])]),_:1}),s[6]||(s[6]=a(" 丰富复杂的功能以及其巴洛克式命令语法可能让人难以驾驭。我们就来探讨一下其中的一些功能，提供一些系统管理员解决某些问题需要的使用技巧。",-1))]),s[33]||(s[33]=p(`<h3 id="避免封锁自己" tabindex="-1">避免封锁自己 <a class="header-anchor" href="#避免封锁自己" aria-label="Permalink to “避免封锁自己”">​</a></h3><p>应用场景：假设你将对公司服务器上的防火墙规则进行修改，你需要避免封锁你自己以及其他同事的情况（这将会带来一定时间和金钱的损失，也许一旦发生马上就有部门打电话找你了）</p><h4 id="技巧-1-开始之前先备份一下-iptables-配置文件。" tabindex="-1">技巧 #1: 开始之前先备份一下 iptables 配置文件。 <a class="header-anchor" href="#技巧-1-开始之前先备份一下-iptables-配置文件。" aria-label="Permalink to “技巧 #1: 开始之前先备份一下 iptables 配置文件。”">​</a></h4><p>用如下命令备份配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/iptables-save &gt; /root/iptables-works</span></span></code></pre></div><h4 id="技巧-2-更妥当的做法-给文件加上时间戳。" tabindex="-1">技巧 #2: 更妥当的做法，给文件加上时间戳。 <a class="header-anchor" href="#技巧-2-更妥当的做法-给文件加上时间戳。" aria-label="Permalink to “技巧 #2: 更妥当的做法，给文件加上时间戳。”">​</a></h4><p>用如下命令加时间戳：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/iptables-save &gt; /root/iptables-works-\`date +%F\`</span></span></code></pre></div><p>然后你就可以生成如下名字的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/root/iptables-works-2018-09-11</span></span></code></pre></div><p>这样万一使得系统不工作了，你也可以很快的利用备份文件恢复原状：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/iptables-restore &lt; /root/iptables-works-2018-09-11</span></span></code></pre></div><h4 id="技巧-3-每次创建-iptables-配置文件副本时-都创建一个指向最新的文件的链接。" tabindex="-1">技巧 #3: 每次创建 iptables 配置文件副本时，都创建一个指向最新的文件的链接。 <a class="header-anchor" href="#技巧-3-每次创建-iptables-配置文件副本时-都创建一个指向最新的文件的链接。" aria-label="Permalink to “技巧 #3: 每次创建 iptables 配置文件副本时，都创建一个指向最新的文件的链接。”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln –s /root/iptables-works-\`date +%F\` /root/iptables-works-latest</span></span></code></pre></div><h4 id="技巧-4-将特定规则放在策略顶部-底部放置通用规则。" tabindex="-1">技巧 #4: 将特定规则放在策略顶部，底部放置通用规则。 <a class="header-anchor" href="#技巧-4-将特定规则放在策略顶部-底部放置通用规则。" aria-label="Permalink to “技巧 #4: 将特定规则放在策略顶部，底部放置通用规则。”">​</a></h4><p>避免在策略顶部使用如下的一些通用规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A INPUT -p tcp --dport 22 -j DROP</span></span></code></pre></div><p>你在规则中指定的条件越多，封锁自己的可能性就越小。不要使用上面非常通用的规则，而是使用如下的规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A INPUT -p tcp --dport 22 –s 10.0.0.0/8 –d 192.168.100.101 -j DROP</span></span></code></pre></div><p>此规则表示在 <code>INPUT</code> 链尾追加一条新规则，将源地址为 <code>10.0.0.0/8</code>、 目的地址是 <code>192.168.100.101</code>、目的端口号是 <code>22</code> （<code>--dport 22</code> ） 的 TCP（<code>-p tcp</code> ）数据包通通丢弃掉。</p><p>还有很多方法可以设置更具体的规则。例如，使用 <code>-i eth0</code> 将会限制这条规则作用于 <code>eth0</code> 网卡，对 <code>eth1</code> 网卡则不生效。</p><h4 id="技巧-5-在策略规则顶部将你的-ip-列入白名单。" tabindex="-1">技巧 #5: 在策略规则顶部将你的 IP 列入白名单。 <a class="header-anchor" href="#技巧-5-在策略规则顶部将你的-ip-列入白名单。" aria-label="Permalink to “技巧 #5: 在策略规则顶部将你的 IP 列入白名单。”">​</a></h4><p>这是一个有效地避免封锁自己的设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -I INPUT -s &lt;your IP&gt; -j ACCEPT</span></span></code></pre></div><p>你需要将该规则添加到策略首位置。<code>-I</code> 表示则策略首部插入规则，<code>-A</code> 表示在策略尾部追加规则。</p><h4 id="技巧-6-理解现有策略中的所有规则。" tabindex="-1">技巧 #6: 理解现有策略中的所有规则。 <a class="header-anchor" href="#技巧-6-理解现有策略中的所有规则。" aria-label="Permalink to “技巧 #6: 理解现有策略中的所有规则。”">​</a></h4><p>不犯错就已经成功了一半。如果你了解 iptables 策略背后的工作原理，使用起来更为得心应手。如果有必要，可以绘制流程图来理清数据包的走向。还要记住：策略的预期效果和实际效果可能完全是两回事。</p><h3 id="设置防火墙策略" tabindex="-1">设置防火墙策略 <a class="header-anchor" href="#设置防火墙策略" aria-label="Permalink to “设置防火墙策略”">​</a></h3><p>应用场景：你希望给工作站配置具有限制性策略的防火墙。</p><h4 id="技巧-1-设置默认规则为丢弃" tabindex="-1">技巧 #1: 设置默认规则为丢弃 <a class="header-anchor" href="#技巧-1-设置默认规则为丢弃" aria-label="Permalink to “技巧 #1: 设置默认规则为丢弃”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set a default policy of DROP</span></span>
<span class="line"><span>*filter</span></span>
<span class="line"><span>:INPUT DROP [0:0]</span></span>
<span class="line"><span>:FORWARD DROP [0:0]</span></span>
<span class="line"><span>:OUTPUT DROP [0:0]</span></span></code></pre></div><h4 id="技巧-2-将用户完成工作所需的最少量服务设置为允许" tabindex="-1">技巧 #2: 将用户完成工作所需的最少量服务设置为允许 <a class="header-anchor" href="#技巧-2-将用户完成工作所需的最少量服务设置为允许" aria-label="Permalink to “技巧 #2: 将用户完成工作所需的最少量服务设置为允许”">​</a></h4><p>该策略需要允许工作站能通过 DHCP（<code>-p udp --dport 67:68 -sport 67:68</code>）来获取 IP 地址、子网掩码以及其他一些信息。对于远程操作，需要允许 SSH 服务（<code>-dport 22</code>），邮件服务（<code>--dport 25</code>），DNS 服务（<code>--dport 53</code>），ping 功能（<code>-p icmp</code>），NTP 服务（<code>--dport 123 --sport 123</code>）以及 HTTP 服务（<code>-dport 80</code>）和 HTTPS 服务（<code>--dport 443</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set a default policy of DROP</span></span>
<span class="line"><span>*filter</span></span>
<span class="line"><span>:INPUT DROP [0:0]</span></span>
<span class="line"><span>:FORWARD DROP [0:0]</span></span>
<span class="line"><span>:OUTPUT DROP [0:0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Accept any related or established connections</span></span>
<span class="line"><span>-I INPUT  1 -m state --state RELATED,ESTABLISHED -j ACCEPT</span></span>
<span class="line"><span>-I OUTPUT 1 -m state --state RELATED,ESTABLISHED -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow all traffic on the loopback interface</span></span>
<span class="line"><span>-A INPUT -i lo -j ACCEPT</span></span>
<span class="line"><span>-A OUTPUT -o lo -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow outbound DHCP request</span></span>
<span class="line"><span>-A OUTPUT –o eth0 -p udp --dport 67:68 --sport 67:68 -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow inbound SSH</span></span>
<span class="line"><span>-A INPUT -i eth0 -p tcp -m tcp --dport 22 -m state --state NEW  -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow outbound email</span></span>
<span class="line"><span>-A OUTPUT -i eth0 -p tcp -m tcp --dport 25 -m state --state NEW  -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Outbound DNS lookups</span></span>
<span class="line"><span>-A OUTPUT -o eth0 -p udp -m udp --dport 53 -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Outbound PING requests</span></span>
<span class="line"><span>-A OUTPUT –o eth0 -p icmp -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Outbound Network Time Protocol (NTP) requests</span></span>
<span class="line"><span>-A OUTPUT –o eth0 -p udp --dport 123 --sport 123 -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Outbound HTTP</span></span>
<span class="line"><span>-A OUTPUT -o eth0 -p tcp -m tcp --dport 80 -m state --state NEW -j ACCEPT</span></span>
<span class="line"><span>-A OUTPUT -o eth0 -p tcp -m tcp --dport 443 -m state --state NEW -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>COMMIT</span></span></code></pre></div><h3 id="限制-ip-地址范围" tabindex="-1">限制 IP 地址范围 <a class="header-anchor" href="#限制-ip-地址范围" aria-label="Permalink to “限制 IP 地址范围”">​</a></h3><p>应用场景：贵公司的 CEO 认为员工在 Facebook 上花费过多的时间，需要采取一些限制措施。CEO 命令下达给 CIO，CIO 命令 CISO，最终任务由你来执行。你决定阻止一切到 Facebook 的访问连接。首先你使用 <code>host</code> 或者 <code>whois</code> 命令来获取 Facebook 的 IP 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host -t a www.facebook.com</span></span>
<span class="line"><span>www.facebook.com is an alias for star.c10r.facebook.com.</span></span>
<span class="line"><span>star.c10r.facebook.com has address 31.13.65.17</span></span>
<span class="line"><span>whois 31.13.65.17 | grep inetnum</span></span>
<span class="line"><span>inetnum:        31.13.64.0 - 31.13.127.255</span></span></code></pre></div>`,37)),e("p",null,[s[8]||(s[8]=a("然后使用 ",-1)),t(i,{href:"http://www.ipaddressguide.com/cidr"},{default:n(()=>[...s[7]||(s[7]=[a("CIDR 到 IPv4 转换",-1)])]),_:1}),s[9]||(s[9]=a(" 页面来将其转换为 CIDR 表示法。然后你得到 ",-1)),s[10]||(s[10]=e("code",null,"31.13.64.0/18",-1)),s[11]||(s[11]=a(" 的地址。输入以下命令来阻止对 Facebook 的访问：",-1))]),s[34]||(s[34]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A OUTPUT -p tcp -i eth0 –o eth1 –d 31.13.64.0/18 -j DROP</span></span></code></pre></div><h3 id="按时间规定做限制-场景1" tabindex="-1">按时间规定做限制 - 场景1 <a class="header-anchor" href="#按时间规定做限制-场景1" aria-label="Permalink to “按时间规定做限制 - 场景1”">​</a></h3><p>应用场景：公司员工强烈反对限制一切对 Facebook 的访问，这导致了 CEO 放宽了要求（考虑到员工的反对以及他的助理提醒说她负责更新他的 Facebook 页面）。然后 CEO 决定允许在午餐时间访问 Facebook（中午 12 点到下午 1 点之间）。假设默认规则是丢弃，使用 iptables 的时间功能便可以实现。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables –A OUTPUT -p tcp -m multiport --dport http,https -i eth0 -o eth1 -m time --timestart 12:00 –timestop 13:00 –d 31.13.64.0/18 -j ACCEPT</span></span></code></pre></div><p>该命令中指定在中午12点（<code>--timestart 12:00</code>）到下午 1 点（<code>--timestop 13:00</code>）之间允许（<code>-j ACCEPT</code>）到 Facebook.com （<code>-d [31.13.64.0/18][5]</code>）的 http 以及 https （<code>-m multiport --dport http,https</code>）的访问。</p><h3 id="按时间规定做限制-场景2" tabindex="-1">按时间规定做限制 - 场景2 <a class="header-anchor" href="#按时间规定做限制-场景2" aria-label="Permalink to “按时间规定做限制 - 场景2”">​</a></h3><p>应用场景：在计划系统维护期间，你需要设置凌晨 2 点到 3 点之间拒绝所有的 TCP 和 UDP 访问，这样维护任务就不会受到干扰。使用两个 iptables 规则可实现：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A INPUT -p tcp -m time --timestart 02:00 --timestop 03:00 -j DROP</span></span>
<span class="line"><span>iptables -A INPUT -p udp -m time --timestart 02:00 --timestop 03:00 -j DROP</span></span></code></pre></div><p>该规则禁止（<code>-j DROP</code>）在凌晨2点（<code>--timestart 02:00</code>）到凌晨3点（<code>--timestop 03:00</code>）之间的 TCP 和 UDP （<code>-p tcp and -p udp</code>）的数据进入（<code>-A INPUT</code>）访问。</p><h3 id="限制连接数量" tabindex="-1">限制连接数量 <a class="header-anchor" href="#限制连接数量" aria-label="Permalink to “限制连接数量”">​</a></h3><p>应用场景：你的 web 服务器有可能受到来自世界各地的 DoS 攻击，为了避免这些攻击，你可以限制单个 IP 地址到你的 web 服务器创建连接的数量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables –A INPUT –p tcp –syn -m multiport -–dport http,https –m connlimit -–connlimit-above 20 –j REJECT -–reject-with-tcp-reset</span></span></code></pre></div><p>分析一下上面的命令。如果单个主机在一分钟之内新建立（<code>-p tcp -syn</code>）超过 20 个（<code>-connlimit-above 20</code>）到你的 web 服务器（<code>--dport http,https</code>）的连接，服务器将拒绝（<code>-j REJECT</code>）建立新的连接，然后通知对方新建连接被拒绝（<code>--reject-with-tcp-reset</code>）。</p><h3 id="监控-iptables-规则" tabindex="-1">监控 iptables 规则 <a class="header-anchor" href="#监控-iptables-规则" aria-label="Permalink to “监控 iptables 规则”">​</a></h3><p>应用场景：由于数据包会遍历链中的规则，iptables 遵循 “首次匹配获胜” 的原则，因此经常匹配的规则应该靠近策略的顶部，而不太频繁匹配的规则应该接近底部。 你怎么知道哪些规则使用最多或最少，可以在顶部或底部附近监控？</p><h4 id="技巧-1-查看规则被访问了多少次" tabindex="-1">技巧 #1: 查看规则被访问了多少次 <a class="header-anchor" href="#技巧-1-查看规则被访问了多少次" aria-label="Permalink to “技巧 #1: 查看规则被访问了多少次”">​</a></h4><p>使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -L -v -n –line-numbers</span></span></code></pre></div><p>用 <code>-L</code> 选项列出链中的所有规则。因为没有指定具体哪条链，所有链规则都会被输出，使用 <code>-v</code> 选项显示详细信息，<code>-n</code> 选项则显示数字格式的数据包和字节计数器，每个规则开头的数值表示该规则在链中的位置。</p><p>根据数据包和字节计数的结果，你可以将访问频率最高的规则放到顶部，将访问频率最低的规则放到底部。</p><h4 id="技巧-2-删除不必要的规则" tabindex="-1">技巧 #2: 删除不必要的规则 <a class="header-anchor" href="#技巧-2-删除不必要的规则" aria-label="Permalink to “技巧 #2: 删除不必要的规则”">​</a></h4><p>哪条规则从来没有被访问过？这些可以被清除掉。用如下命令查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -nvL | grep -v &quot;0     0&quot;</span></span></code></pre></div><p>注意：两个数字 0 之间不是 Tab 键，而是 <strong>5</strong> 个空格。</p><h4 id="技巧-3-监控正在发生什么" tabindex="-1">技巧 #3: 监控正在发生什么 <a class="header-anchor" href="#技巧-3-监控正在发生什么" aria-label="Permalink to “技巧 #3: 监控正在发生什么”">​</a></h4><p>可能你也想像使用 <code>top</code> 命令一样来实时监控 iptables 的情况。使用如下命令来动态监视 iptables 中的活动，并仅显示正在遍历的规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>watch --interval=5 &#39;iptables -nvL | grep -v &quot;0     0&quot;&#39;</span></span></code></pre></div><p><code>watch</code> 命令通过参数 <code>iptables -nvL | grep -v “0 0“</code> 每隔 5 秒输出 iptables 的动态。这条命令允许你查看数据包和字节计数的变化。</p><h3 id="输出日志" tabindex="-1">输出日志 <a class="header-anchor" href="#输出日志" aria-label="Permalink to “输出日志”">​</a></h3><p>应用场景：经理觉得你这个防火墙员工的工作质量杠杠的，但如果能有网络流量活动日志最好了。有时候这比写一份有关工作的报告更有效。</p>`,30)),e("p",null,[s[13]||(s[13]=a("使用工具 ",-1)),t(i,{href:"http://fwlogwatch.inside-security.de/"},{default:n(()=>[...s[12]||(s[12]=[a("FWLogwatch",-1)])]),_:1}),s[14]||(s[14]=a(" 基于 iptables 防火墙记录来生成日志报告。FWLogwatch 工具支持很多形式的报告并且也提供了很多分析功能。它生成的日志以及月报告使得管理员可以节省大量时间并且还更好地管理网络，甚至减少未被注意的潜在攻击。",-1))]),s[35]||(s[35]=e("p",null,"这里是一个 FWLogwatch 生成的报告示例：",-1)),s[36]||(s[36]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/uploads/fwlogwatch.png",alt:""})],-1)),s[37]||(s[37]=e("h3",{id:"不要满足于允许和丢弃规则",tabindex:"-1"},[a("不要满足于允许和丢弃规则 "),e("a",{class:"header-anchor",href:"#不要满足于允许和丢弃规则","aria-label":"Permalink to “不要满足于允许和丢弃规则”"},"​")],-1)),s[38]||(s[38]=e("p",null,"本文中已经涵盖了 iptables 的很多方面，从避免封锁自己、配置 iptables 防火墙以及监控 iptables 中的活动等等方面介绍了 iptables。你可以从这里开始探索 iptables 甚至获取更多的使用技巧。",-1)),s[39]||(s[39]=e("hr",null,null,-1)),e("p",null,[s[16]||(s[16]=a("via: ",-1)),t(i,{href:"https://opensource.com/article/18/10/iptables-tips-and-tricks"},{default:n(()=>[...s[15]||(s[15]=[a("https://opensource.com/article/18/10/iptables-tips-and-tricks",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=a("作者：",-1)),t(i,{href:"https://opensource.com/users/greptile"},{default:n(()=>[...s[17]||(s[17]=[a("Gary Smith",-1)])]),_:1}),s[22]||(s[22]=a(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[18]||(s[18]=[a("lujun9972",-1)])]),_:1}),s[23]||(s[23]=a(" 译者：",-1)),t(i,{href:"https://github.com/jrglinux"},{default:n(()=>[...s[19]||(s[19]=[a("jrg",-1)])]),_:1}),s[24]||(s[24]=a(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[20]||(s[20]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=a("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[25]||(s[25]=[a("LCTT",-1)])]),_:1}),s[28]||(s[28]=a(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[26]||(s[26]=[a("Linux中国",-1)])]),_:1}),s[29]||(s[29]=a(" 荣誉推出",-1))])])}const C=l(h,[["render",c]]);export{T as __pageData,C as default};
